<?php require __DIR__.'/core.php'; require __DIR__.'/views.php'; header('Cache-Control: no-store'); $notice=''; $errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
 check_csrf(); $name=trim((string)($_POST['name']??'')); $phone=trim(strtr((string)($_POST['phone']??''),['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9'])); $message=trim((string)($_POST['message']??'')); $service=(string)($_POST['service']??'');
 if (!$name || strlen($name)>200) $errors[]='نام خود را وارد کنید (حداکثر ۱۰۰ حرف).';
 if (!preg_match('/^09[0-9]{9}$/',$phone)) $errors[]='شماره موبایل را به صورت ۰۹۱۲۳۴۵۶۷۸۹ وارد کنید.';
 if (strlen($message)<10 || strlen($message)>6000) $errors[]='لطفاً توضیحی بین ۱۰ تا ۳۰۰۰ حرف بنویسید.';
 if (!in_array($service,array_column($site['services'],'title'),true)) $errors[]='خدمت مورد نظر را انتخاب کنید.';
 if (!empty($_POST['website'])) $errors[]='درخواست معتبر نیست.';
 if (time()-($_SESSION['last_message']??0)<60) $errors[]='برای ارسال پیام بعدی یک دقیقه صبر کنید.';
 if (!$errors) { try { update_json('messages',function($messages)use($name,$phone,$message,$service){$messages[]=['id'=>bin2hex(random_bytes(8)),'name'=>$name,'phone'=>$phone,'message'=>$message,'service'=>$service,'date'=>gmdate('c'),'read'=>false];return $messages;}); $_SESSION['last_message']=time(); $_SESSION['sent']=true; header('Location: /?sent=1#contact'); exit; } catch(Throwable $ex){$errors[]='پیام ذخیره نشد؛ لطفاً دوباره تلاش کنید یا تماس بگیرید.';} }
}
$sent=!empty($_SESSION['sent']); unset($_SESSION['sent']);
